const S={edition:'PIM',page:'Home',groupExpanded:{},parentMenu:false,companyOpen:false,quickOpen:false,compact:false,sideSections:{},mobile:false,modal:null,formTitle:'',formOwner:'',formNote:'',search:'',status:'All',sort:'newest',toast:'',detail:null,feedbackRating:'Useful',feedbackText:'',reviewer:'',records:read('prime:records',[]),feedback:read('prime:feedback',[]),notificationsUnread:true,profileMenu:false,period:'This week',periodOpen:false,tourStep:0,cart:[],posSearch:'',posPayMethod:'Card'};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function idOf(v){return v.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-')}
function allNav(){return [...shared,...editionMeta[S.edition].groups]}
function titleForCurrent(){return S.page==='Home'?'Good afternoon, Demo':S.page}
function initialRoute(){const h=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);if(['PIM','RIM','TIM'].includes(h[0]))S.edition=h[0];if(h[1])S.page=decodeURIComponent(h.slice(1).join('/'));}
function navigate(page,edition=S.edition){S.quickOpen=false;S.page=page;S.edition=edition;S.mobile=false;S.parentMenu=false;S.search='';S.status='All';S.detail=null;location.hash='/'+edition+'/'+encodeURIComponent(page);draw()}
function switchEdition(edition){S.parentMenu=false;S.quickOpen=false;S.sideSections={};navigate('Home',edition)}
function getGroup(name){for(const [,entries] of allNav())for(const [label,children] of entries)if(label===name||children.includes(name))return label;return name}
