function primeSwitcher(){const active=S.edition;return `<div class="switch-products">
${Object.entries(editionMeta).map(([key,v])=>`<button class="switch-option ${active===key?'selected':''}" data-edition="${key}"><span class="product-code ${key.toLowerCase()}">${key}</span><span>${key==='PIM'?'Product':key==='RIM'?'Retail':'Tool'} Inventory</span><small>${active===key?'✓ ':''}Active</small></button>`).join('')}
<div class="product-explore"><strong>Explore Products</strong>${[['HRM','Human Resources'],['FAM','Facility Management']].map(([key,title])=>`<button class="explore-row" data-action="explore" data-name="${key}"><span class="product-code inactive">${key}</span><span>${title}</span><b>Explore</b></button>`).join('')}</div></div>`}
function navigationRow(label,target,children=[],count=0){let expanded=!!S.groupExpanded[S.edition+':'+target],active=S.page===target;return `<div class="nav-holder"><button class="prime-navrow ${active?'active':''}" data-nav="${esc(target)}" title="${esc(label)}"><span class="navico">${icon(sideIcons[label]||icons[target]||'package')}</span><span class="navtext">${esc(label)}</span>${count?`<span class="prime-count">${count}</span>`:''}${children.length?`<span class="prime-chevron" data-action="expand" data-name="${esc(target)}" style="transform:rotate(${expanded?90:0}deg)">${icon('chevron')}</span>`:''}</button>${children.length&&expanded?`<div class="prime-subitems">${children.map(ch=>`<button class="prime-subitem ${S.page===ch?'active':''}" data-nav="${esc(ch)}">${esc(ch)}</button>`).join('')}</div>`:''}</div>`}
function childrenFor(name){const ent=editionMeta[S.edition].groups.flatMap(g=>g[1]).find(([n])=>n===name);return ent?ent[1]:[]}
function sideSection(name,content,theme='blue'){const expanded=S.sideSections[name]!==false;return `<div class="prime-section ${theme}"><button class="prime-section-title" data-action="section-toggle" data-name="${esc(name)}" aria-expanded="${expanded}"><span>${esc(name)}</span><span style="transform:rotate(${expanded?0:-90}deg)">${icon('chevron')}</span></button>${expanded?`<div class="prime-section-body">${content}</div>`:''}</div>`}
function sidebar(){const edition=S.edition;const c=editionMeta[edition];let common=['Overview','Tasks','Chat','Notifications','Documents','Activity Log','Reviews & Approvals'];let commonLinks=common.map(n=>navigationRow(n,n==='Overview'?'Home':n,[],n==='Tasks'?12:n==='Chat'?3:n==='Notifications'?8:n==='Reviews & Approvals'?5:0)).join('');const operations=snapshotNav[edition].map(([label,target])=>navigationRow(label,target,childrenFor(target))).join('');const extras=extraNav[edition].map(([label,target])=>navigationRow(label,target,childrenFor(target))).join('');let admin=['Team & Access','Configuration','Policies','Billing & Plans','Audit & Diagnostics','Profile','Settings','Help & Support'];const adminMap={'Team & Access':'Team','Configuration':'Setup','Policies':'Policies','Billing & Plans':'Billing','Audit & Diagnostics':'Audit & diagnostics','Profile':'Profile','Settings':'Settings','Help & Support':'Help'};const adminLinks=admin.map(label=>navigationRow(label,adminMap[label],[])).join('');
let top=`<div class="prime-top"><div class="prime-brand"><button class="brand-icon" data-action="prime-overview" title="PRIME Overview"><img src="assets/prime-mark.svg" alt="PRIME logo" /></button><div><strong>PRIME</strong><small>${S.compact?'':'Inventory Management'}</small></div><button class="sidebar-collapse" data-action="sidebar-collapse" title="Collapse sidebar">${icon('chevron')}</button></div><button class="prime-company" data-action="company-toggle"><span class="company-symbol">${icon('store')}</span><span class="company-info"><b>ABC Properties Ltd.</b></span>${icon('chevron')}</button>${S.companyOpen?`<div class="prime-fly"><button class="switch-option selected" data-action="company-toggle">ABC Properties Ltd. · Demo</button></div>`:''}<button class="prime-current-product" data-action="edition-toggle"><span class="current-icon ${edition.toLowerCase()}">${icon('package')}</span><span class="current-title"><b>Switch Product</b><small><em class="product-code ${edition.toLowerCase()}">${edition}</em> ${edition==='PIM'?'Product':edition==='RIM'?'Retail':'Tool'} Inventory</small></span>${icon('chevron')}</button>${S.parentMenu?primeSwitcher():''}<button class="prime-create" data-action="quick-toggle">${icon('plus')} <span>Create New</span><span class="create-chevron">${icon('chevron')}</span></button>${S.quickOpen?`<div class="prime-fly create-list">${quickOptions[edition].map(n=>`<button data-form="${esc(n)}">${icon('plus')} ${esc(n)}</button>`).join('')}</div>`:''}</div>`;
const primeMode=S.page==='PRIME Overview'||S.page==='My Products';
const global=`${navigationRow('PRIME Overview','PRIME Overview')}${navigationRow('My Products','My Products')}${navigationRow('Tasks','Tasks',[],12)}${navigationRow('Chat','Chat',[],3)}${navigationRow('Notifications','Notifications',[],8)}${navigationRow('Documents','Documents')}${navigationRow('Profile','Profile')}${navigationRow('Activity Log','Activity Log')}${navigationRow('Reviews & Approvals','Reviews & Approvals',[],5)}`;
const content=primeMode?`<div class="prime-overview-rows">${global}</div>${sideSection('MANAGEMENT',adminLinks,'white')}`:`${sideSection('WORKSPACE',commonLinks,'blue')}${sideSection(edition+' OPERATIONS',operations,edition==='RIM'?'rose':edition==='TIM'?'mint':'blue')}${sideSection('MORE MODULES',extras,'white')}${sideSection('INSIGHTS',navigationRow('Analytics','Analytics',childrenFor('Analytics'))+navigationRow('Reports','Reports',childrenFor('Reports')),'violet')}${sideSection('ADMINISTRATION',adminLinks,'mint')}`;
return `<div class="sidebar prime-sidebar ${S.compact?'prime-collapsed':''}">${top}<div class="side-scroll prime-scroll">${content}</div><div class="prime-footer"><button class="profile" data-action="profile"><span class="avatar-profile">JD</span><span><b>John Doe</b><small>Admin</small></span>${icon('chevron')}</button><button class="plan-tile" data-action="subscription"><span class="plan-active"></span><span><b>Organisation Plan</b><small>3 of 3 products active</small></span>${icon('chevron')}</button></div></div>`}
function primeOverview(){return `<section class="card panel"><div class="panel-top"><h2>PRIME Overview</h2><span>ABC Properties Ltd.</span></div><p class="prime-explainer">Your products share one organisation, team and workspace. Select a product to explore its operations.</p><div class="prime-product-cards">${Object.entries(editionMeta).map(([e,v])=>`<button class="prime-product-card" data-edition="${e}"><span class="product-code ${e.toLowerCase()}">${e}</span><strong>${esc(v.full)}</strong><span>${esc(v.desc)}</span><b>Open workspace →</b></button>`).join('')}</div></section><section class="card panel panel-group"><div class="panel-top"><h2>My Products</h2><span>3 of 3 active</span></div><div class="prime-product-cards">${Object.entries(editionMeta).map(([e,v])=>`<div class="prime-product-card status-card"><span class="product-code ${e.toLowerCase()}">${e}</span><strong>${esc(v.full)}</strong><span class="status green">Active</span><button class="secondary" data-edition="${e}">Open ${e} →</button></div>`).join('')}</div></section>`}
function mobileNav(){return `<div class="mobile-bottom">${[['Home','home'],['Tasks','checklist'],['Search','search'],['Chat','chat'],['More','menu']].map(([a,b])=>`<button data-action="${a==='More'?'mobile':a==='Search'?'focus-search':'navigate'}" data-name="${a}" class="${S.page===a?'active':''}">${icon(b)}${a}</button>`).join('')}</div>`}
function topbar(){return `<header class="topbar"><button class="icon-btn mobile-menu-btn" aria-label="Open menu" data-action="mobile">${icon('menu')}</button><label class="searchbox">${icon('search')}<input id="global-search" aria-label="Search this workspace" placeholder="Search or scan items, assets, requests..." value="${esc(S.search)}"><span class="search-shortcut">⌘ K</span></label><div class="top-grow"></div><span class="edition-pill">${S.edition}</span><button class="topbar-chat" data-nav="Chat" aria-label="Open Chat">${icon('chat')} Chat</button><button class="icon-btn" data-nav="Help" aria-label="Help">${icon('help')}</button><button class="icon-btn" data-nav="Notifications" aria-label="Notifications">${icon('bell')}${S.notificationsUnread?'<i class="dot"></i>':''}</button><button class="user-menu-trigger" data-action="profile-menu-toggle" aria-expanded="${S.profileMenu?'true':'false'}" aria-label="User options"><span class="avatar">DO</span><span class="user-text"><strong>Demo Owner</strong><small>Demo Engineering Ltd</small></span>${icon('chevron')}</button>${S.profileMenu?`<div class="profile-dropdown" role="menu"><div class="profile-head"><span class="avatar">DO</span><span><b>Demo Owner</b><small>owner@demo.test</small></span></div>${[['Profile','Profile'],['Account settings','Settings'],['Security','Security'],['Notification settings','Notifications'],['Help','Help']].map(([label,target])=>`<button role="menuitem" data-nav="${target}">${icon(label==='Profile'?'people':label==='Help'?'help':label==='Notification settings'?'bell':'settings')} ${label}</button>`).join('')}<div class="profile-divider"></div><button role="menuitem" data-action="sign-out">${icon('arrow')} Sign out</button></div>`:''}</header>`}

function topIntro(){if(S.page==='Home')return '';return `<div class="breadcrumb">PRIME / ${S.edition} / ${esc(getGroup(S.page))} / ${esc(S.page)}</div><div class="heading-row"><div><h1>${esc(titleForCurrent())}</h1><p>${esc(descriptionFor(S.page))}</p></div><div class="actions"><button class="secondary" data-action="feedback">${icon('chat')} Give feedback</button><button class="primary" data-action="quick">${icon('plus')} New action</button></div></div>`}

function descriptionFor(page){const descriptions={Profile:'View and update your demo profile',Security:'Review sign-in and account security',Chat:'Conversations and mentions linked to records',Home:'Your operational overview',Tasks:'Track work and assignments across your organisation',Chat:'Conversations and mentions linked to records',Notifications:'Events that need your attention',Billing:'View subscription, usage and wallet information',Settings:'Manage company preferences and integrations',Setup:'Configure your workspace and readiness checklist',Help:'Find answers and share feedback',Reports:'Download reports or schedule delivery',Documents:'File library and document versions',Policies:'Review inventory, approval and security rules'};return descriptions[page]||`Review and manage ${page.toLowerCase()} in your ${S.edition} workspace`}
function statusCls(s){let v=(s||'').toLowerCase();return /pending|due|overdue|review|inspection|draft/.test(v)?'amber':/fulfilled|paid|approved|available|completed|delivered|passed/.test(v)?'green':/rejected|missing|failed|cancelled/.test(v)?'red':'blue'}
function seededRows(page){let p=page.toLowerCase();if(S.page==='Tasks'||/task/.test(p))return [['TASK-1007','Review outstanding approval','Operations','Pending'],['TASK-1006','Complete stock count','Storekeeper','In progress'],['TASK-1003','Check employee custody','Engineering','Completed']];if(/approval/.test(p))return [['APR-2041','Material request approval','Engineering','Pending'],['APR-2040','Purchase order decision','Finance','Pending'],['APR-2039','Stock adjustment authorisation','Warehouse','Approved']];if(/supplier/.test(p))return [['SUP-011','Atlas Industrial Supplies','Procurement','Active'],['SUP-012','Broadway Components','Procurement','Active'],['SUP-013','Metro Equipment Co.','Maintenance','Under review']];if(/calibration/.test(p))return [['CAL-074','Torque wrench','Workshop','Calibration due'],['CAL-075','Pressure gauge','Site 02','Scheduled'],['CAL-076','Digital micrometer','Tool crib','Completed']];if(/inspection/.test(p))return [['INSP-231','Pre-use inspection','Main tool crib','Passed'],['INSP-230','Lifting harness','Site C','Under review'],['INSP-229','Portable generator','Workshop','Failed']];if(/people|employee|team|personnel|technician|cashier/.test(p))return [['EMP-040','John Ade','Operations','Active'],['EMP-041','Amaka Bello','Procurement','Active'],['EMP-042','Mary Okafor','Engineering','Active']];if(/report|analytics|budget/.test(p))return [['REP-011','Monthly performance','Operations','Completed'],['REP-012','Stock value analysis','Finance','Available'],['REP-013','Exceptions report','Compliance','Under review']];if(/product|asset|stock|inventory/.test(p))return [['STK-0041','Electrical connectors','Central warehouse','Available'],['STK-0042','Safety gloves','Workshop','Low stock'],['AST-0244','Laptop workstation','IT Services','Assigned']];return editionMeta[S.edition].sample.map(a=>[...a])}
function rowsFor(page){const saved=S.records.filter(r=>r.edition===S.edition&&(r.module===getGroup(page)||r.module===page||page==='All records')).map(r=>[r.ref,r.title,r.owner,r.status]);return [...saved,...seededRows(page)]}
function overview(){const c=editionMeta[S.edition];const period=S.period;const details=period==='This week'?['Last week','Weekly average','Busiest week']:period==='This month'?['Last month','Monthly average','Busiest week']:['Previous period','Period average','Busiest period'];const quick=S.edition==='PIM'?['Request items','Ask to Buy','Receive Delivery','Add an item','Register an asset','View reports']:S.edition==='RIM'?['Open POS','Create sales order','Receive stock','Add a product','Process return','View reports']:['Check out a tool','Request equipment','Record a return','Register a tool','Start inspection','View reports'];const names=S.edition==='PIM'?['Requests raised','Approval decisions','Stock movements','Assets registered']:S.edition==='RIM'?['Sales completed','Orders raised','Stock movements','Products added']:['Tools issued','Returns processed','Inspections done','Calibration checks'];const ic=['package','check','chart','boxes'];const periodOpt=['This week','This month','3 months','6 months','1 year'];return `<div class="dashboard-grid"><div class="dashboard-left"><section class="dash-hero"><div class="dash-hero-text"><div class="dash-date">${icon('calendar')} ${new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date())}</div><h1>Good morning, Demo <span role="img" aria-label="Hello">👋</span></h1><button class="dash-attention" data-nav="Tasks">6 things need your attention</button> today.</div><div class="hero-boxes" aria-hidden="true"><div class="cube cube-one"></div><div class="cube cube-two"></div><div class="cube cube-three"></div></div></section><section class="card dash-quick"><div class="dash-section-head"><span>QUICK ACTIONS</span><button class="quiet-link" data-action="quick">All actions ${icon('arrow')}</button></div><div class="dash-action-grid">${quick.map((label,i)=>`<button class="dash-action" data-form="${esc(label)}"><span class="dash-action-icon shade-${i}">${icon(['package','cart','truck','file','boxes','chart'][i])}</span><span>${esc(label)}</span></button>`).join('')}</div></section><section class="card dash-activity"><div class="dash-section-head"><h2>Key activity ${period.toLowerCase()}</h2><div class="period-picker"><button class="period-trigger" data-action="period-toggle" aria-expanded="${S.periodOpen?'true':'false'}">${period} ${icon('chevron')}</button>${S.periodOpen?`<div class="period-options">${periodOpt.map(v=>`<button data-action="period-set" data-period="${v}" class="${v===period?'chosen':''}">${v}${v===period?' ✓':''}</button>`).join('')}</div>`:''}</div></div><div class="dash-activity-cards">${names.map((name,i)=>`<div class="activity-card"><div class="activity-title"><span class="activity-icon shade-${i}">${icon(ic[i])}</span><strong>${esc(name)}</strong></div><div class="activity-value">0 <small>${period.toLowerCase()}</small></div><div class="activity-details"><div>${details[0]} <strong>0</strong></div><div>${details[1]} <strong>0.5</strong></div><div>${details[2]} <strong>—</strong></div></div></div>`).join('')}</div></section><section class="dash-explore"><div class="explore-heading"><h2>Explore more</h2><p>Tools and settings to get the most from your inventory management.</p></div><div class="explore-cards">${[['Invite your team','Add users and set roles','Team','people'],['Configure settings','Set up your locations and rules','Setup','settings'],['Learn the basics','Guides and tutorials','Help','help'],['Give feedback','Help us improve','feedback','chat']].map(([title,desc,target,i])=>`<button class="explore-card" ${target==='feedback'?'data-action="feedback"':`data-nav="${target}"`}><span class="dash-action-icon shade-${title==='Invite your team'?0:title==='Configure settings'?1:title==='Learn the basics'?4:2}">${icon(i)}</span><span><b>${esc(title)}</b><small>${esc(desc)}</small></span></button>`).join('')}</div></section>${classicBelowFold()}</div><div class="dashboard-right"><button class="card dash-company" data-nav="Setup"><span class="dash-action-icon shade-1">${icon('store')}</span><span><small>Company</small><strong>Demo Engineering Ltd</strong><small>One company · 4 locations</small><em>● ${S.edition}</em></span></button><section class="card dash-subscription"><h3>Your plan</h3><div class="plan-detail"><span class="dash-action-icon shade-4">${icon('package')}</span><span><strong>${S.edition} · Basic</strong><small>Active</small></span></div><div class="plan-actions"><button data-nav="Billing">Manage plan →</button><button data-nav="Billing">Billing & invoices</button></div></section><section class="card dash-usage"><h3>Plan usage and your access</h3><p>Usage · ${S.edition}</p>${[['Users','4 of unlimited'],['Companies','1 of unlimited'],['Sites','1 of unlimited'],['Products','8 of unlimited'],['Warehouses and stores','1 of unlimited']].map(([n,v])=>`<div class="usage-row"><span>${n}</span><b>${v}</b></div>`).join('')}<button class="usage-link" data-nav="Billing">View in subscription</button></section><section class="dash-help"><div class="help-head"><span class="dash-action-icon shade-0">${icon('help')}</span><span><strong>Need help?</strong><small>Our team is here to help you.</small></span></div><button data-action="support" class="help-button">Contact support ${icon('arrow')}</button></section></div></div>`}

/* Classic sections from the original PRIME/PIM dashboard screenshots.
   This public prototype uses fictional records; no server state is read. */
const dashboardContext={
PIM:{tasks:[['Waiting for your approval','PIM-REQ-2026-000002 · 1 item from Main warehouse','Approvals','1'],['Deliveries to receive','PIM-PO-2026-000001 from Atlas Building Supplies','Procurement','2'],['Orders the supplier has not confirmed','PIM-PO-2026-000001 · Awaiting acknowledgement','Procurement','2'],['Late delivery: PIM-PO-2026-000001','Expected delivery 5 Oct 2026','Procurement','Soon']],health:[['Out of stock','0'],['Below minimum','0'],['Expired or expiring batches','0'],['Overstocked','0']],healthDetail:'8 products across 8 stock lines',activity:[['AO','Amaka Obi submitted a material request','PIM-REQ-2026-000004','13 Oct 2026, 03:48','Material requests'],['DO','Demo Owner sent a purchase order','PIM-PO-2026-000002','10 Oct 2026, 08:45','Procurement'],['DO','Demo Owner approved a purchase order','PIM-PO-2026-000002','10 Oct 2026, 08:45','Approvals'],['DO','Demo Owner drafted a purchase order','PIM-PO-2026-000002','10 Oct 2026, 08:45','Procurement'],['AO','Amaka Obi drafted a material request','PIM-REQ-2026-000004','7 Oct 2026, 09:13','Material requests']],requestTitle:'My material requests',empty:'You have not asked for anything yet.',requestCTA:'Request items',requestForm:'Request items'},
RIM:{tasks:[['Orders waiting for dispatch','18 paid orders require picking','Fulfilment','18'],['Stock below minimum','8 retail products need replenishment','Inventory','8'],['Customer returns to inspect','5 requests await a condition check','Returns & refunds','5'],['Till closing','Review the current cashier session','Point of sale','Soon']],health:[['Out of stock','4'],['Below minimum','8'],['Damaged or quarantined','2'],['Overstocked','3']],healthDetail:'3 stores and 1 central warehouse',activity:[['RM','Retail Manager confirmed an order','RIM-ORD-2026-0321','20 Oct 2026, 12:45','Sales & orders'],['CS','Cashier completed a POS sale','RIM-POS-2026-0055','20 Oct 2026, 11:35','Point of sale'],['FO','Fulfilment Officer packed an order','RIM-ORD-2026-0320','20 Oct 2026, 10:05','Fulfilment'],['RM','Retail Manager opened a transfer','RIM-TRF-2026-0012','19 Oct 2026, 15:30','Inventory']],requestTitle:'My sales orders',empty:'You have no new orders yet.',requestCTA:'Create sales order',requestForm:'Create sales order'},
TIM:{tasks:[['Overdue tool returns','19 tools are due back from assigned staff','Check-out & check-in','19'],['Calibration approaching','11 tools need calibration within 30 days','Calibration','11'],['Inspections to complete','4 failed pre-use checks require review','Inspections','4'],['Open maintenance order','Generator servicing is awaiting parts','Work orders','Soon']],health:[['Ready for issue','1284'],['Checked out','372'],['In maintenance','19'],['Calibration overdue','11']],healthDetail:'Tools controlled across 6 active sites',activity:[['TC','Tool Crib Manager checked in equipment','TIM-TOOL-0044','20 Oct 2026, 12:00','Check-out & check-in'],['CO','Calibration Officer booked service','TIM-CAL-0074','20 Oct 2026, 11:10','Calibration'],['MT','Maintenance Manager opened a job','TIM-WO-0093','19 Oct 2026, 16:44','Work orders'],['ST','Site Technician completed inspection','TIM-INSP-0231','19 Oct 2026, 09:30','Inspections']],requestTitle:'My tool requests',empty:'You have not requested any tools.',requestCTA:'Request equipment',requestForm:'Request equipment'}
};
function classicBelowFold(){const data=dashboardContext[S.edition];const checklist=[['Workspace configured',false],['Billing active',true],['Location configured',true],['Add products',true],['Add suppliers',true],['Enter opening stock',true],['Invite more team members',true]];return `<div class="classic-lower">
<section class="classic-pair">
 <div class="card classic-panel"><div class="classic-panel-head"><div><h2>My to-do <span class="classic-count">${data.tasks.length+2}</span></h2></div><button class="quiet-link" data-nav="Tasks">View all ${icon('arrow')}</button></div><div class="classic-task-list">${data.tasks.map(([title,description,target,count],i)=>`<button class="classic-task" data-nav="${esc(target)}"><span class="classic-task-icon ${i===3?'warn':''}">${icon(i===3?'alert':i===1?'truck':'check')}</span><span class="classic-task-copy"><strong>${esc(title)}</strong><small>${esc(description)}</small></span><span class="classic-task-count ${count==='Soon'?'soon':''}">${esc(count)}</span>${icon('chevron')}</button>`).join('')}</div></div>
 <div class="card classic-panel"><div class="classic-panel-head"><h2>${S.edition==='PIM'?'Stock health':S.edition==='RIM'?'Store stock health':'Tool readiness'}</h2><button class="quiet-link" data-nav="${S.edition==='TIM'?'Tools & equipment':'Stock'}">Details ${icon('arrow')}</button></div><div class="classic-health-body"><div class="classic-health-ring" role="img" aria-label="Health score: ${S.edition==='PIM'?90:S.edition==='RIM'?83:88} out of 100"><div><strong>${S.edition==='PIM'?90:S.edition==='RIM'?83:88}</strong><span>/100</span><small>● Good</small></div></div><div class="classic-health-lines">${data.health.map(([label,value])=>`<div><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('')}</div></div><div class="classic-health-footer">${icon('package')} ${esc(data.healthDetail)}</div></div>
</section>
<section class="classic-pair">
<div class="card classic-panel"><div class="classic-panel-head"><h2>Recent activity</h2><button class="quiet-link" data-nav="Activity">All activity ${icon('arrow')}</button></div><div class="classic-activity-list">${data.activity.map(([initial,action,ref,date,target])=>`<button class="classic-activity" data-nav="${esc(target)}"><span class="classic-activity-avatar ${initial==='AO'?'mint':''}">${esc(initial)}</span><span class="classic-activity-text"><strong>${esc(action)}</strong><small>${esc(ref)}</small></span><span class="classic-activity-date">${esc(date)}</span></button>`).join('')}</div></div>
<div class="card classic-panel classic-request-panel"><div class="classic-panel-head"><h2>${esc(data.requestTitle)}</h2><button class="quiet-link" data-nav="${S.edition==='PIM'?'Material requests':S.edition==='RIM'?'Sales & orders':'Check-out & check-in'}">View all ${icon('arrow')}</button></div><div class="classic-empty"><div class="classic-empty-art">${icon(S.edition==='TIM'?'tool':S.edition==='RIM'?'cart':'file')}<span>＋</span></div><p>${esc(data.empty)}</p><button class="primary" data-form="${esc(data.requestForm)}">${icon('plus')} ${esc(data.requestCTA)}</button></div></div>
</section>
<section class="classic-pair classic-last">
<div class="card classic-panel"><div class="classic-panel-head"><h2>${icon('package')} Get started with ${S.edition}</h2><button class="quiet-link" data-nav="Setup">Open setup ${icon('arrow')}</button></div><div class="classic-setup-top"><div class="classic-progress" role="img" aria-label="Workspace readiness: 61 percent"><span>61%</span></div><p>1 step left · Finish your workspace setup to get the most out of PRIME.</p></div><div class="classic-checklist">${checklist.map(([label,done])=>`<button data-nav="Setup" class="classic-check-item"><span class="${done?'done':'todo'}">${done?'✓':'◯'}</span><span>${esc(label)}</span>${done?'':'<b>To do</b>'}</button>`).join('')}</div></div>
<div class="classic-tour"><div class="classic-tour-copy"><h3>New here, or showing someone round?</h3><p>A two-minute tour of the menu, search, your to-do and Create New.</p><button class="primary" data-action="quick-tour">${icon('play')} Watch quick tour</button></div><div class="classic-tour-art" aria-hidden="true"><div class="classic-tour-display">${icon('chart')}<i></i></div><div class="classic-tour-box"></div></div></div>
</section></div>`}
function catalogGuide(page){let idx=allNav().flatMap(g=>g[1]).find(([name,ch])=>name===page||ch.includes(page));let subs=idx?idx[1]:[];return subs.length?`<section class="card panel panel-group"><div class="panel-top"><h2>Explore ${esc(page)}</h2><span>${subs.length} workflows</span></div><div class="list-guide">${subs.slice(0,18).map(name=>`<button class="guide-card" style="text-align:left;cursor:pointer" data-nav="${esc(name)}"><strong>${esc(name)}</strong>Open this workflow ${icon('arrow')}</button>`).join('')}</div></section>`:''}
function profilePage(){return `<div class="card panel" style="max-width:780px"><div class="panel-top"><h2>My profile</h2><span class="status blue">Demo account</span></div><div class="profile-form-preview"><span class="avatar avatar-big">DO</span><div><h3>Demo Owner</h3><p>owner@demo.test</p></div></div><div class="profile-meta"><div><label>Full name</label><div>Demo Owner</div></div><div><label>Email address</label><div>owner@demo.test</div></div><div><label>Organisation</label><div>Demo Engineering Ltd</div></div><div><label>Role</label><div>Administrator</div></div></div><div class="info-bar">Profile changes require an authenticated account. This preview uses example data.</div></div>`}
function settingsPage(){return `<div class="card panel" style="max-width:850px"><div class="panel-top"><h2>Settings</h2><span>Workspace and account</span></div><div class="settings-list">${[['Profile','View your account details'],['Security','Password and sign-in'],['Notifications','Email and alert preferences'],['Setup','Company configuration'],['Policies','Operational policies'],['Billing','Plans and invoices']].map(([n,d])=>`<button class="settings-link" data-nav="${n}"><b>${n}</b><span>${d}</span>${icon('chevron')}</button>`).join('')}</div></div>`}
function modulePage(){const page=S.page;
const rows=rowsFor(page).filter(r=>{const hay=r.join(' ').toLowerCase();return (!S.search||hay.includes(S.search.toLowerCase()))&&(S.status==='All'||r[3]===S.status)});const opts=['All',...new Set(rowsFor(page).map(r=>r[3]))];const cols=S.edition==='TIM'?['Reference','Equipment / record','Responsible','Status','Action']:S.edition==='RIM'?['Reference','Order / product','Store / customer','Status','Action']:['Reference','Item / record','Location / department','Status','Action'];
if(page==='Profile')return profilePage();if(page==='Settings')return settingsPage();if(page==='Point of sale'||page==='Open POS')return posPage();if(page==='Leave feedback')return feedbackPage();if(page==='Edition selector')return editionSelector();
return `<section class="kpis">${[['All records',rowsFor(page).length,'In this view'],['Awaiting action',rowsFor(page).filter(r=>/pending|due|review/i.test(r[3])).length,'Open items'],['Updated today',2,'Recent changes'],['Edition',S.edition,'Active workspace']].map((r,i)=>`<div class="card kpi"><div class="kpi-head"><span>${esc(r[0])}</span><div class="kpi-icon">${icon('chart')}</div></div><div class="kpi-val">${esc(r[1])}</div><div class="kpi-foot">${esc(r[2])}</div></div>`).join('')}</section><div class="card panel-group"><div class="table-toolbar"><div><h2>${esc(page)} records</h2><p>Review, search or open a sample record</p></div><div class="toolbar-controls"><select class="mini-select" id="status-filter" aria-label="Filter by status">${opts.map(x=>`<option ${S.status===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="secondary" data-action="export">${icon('download')} Export CSV</button></div></div><div class="table-scroller"><table class="grid-table"><thead><tr>${cols.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r[0])}</strong></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td><td><span class="status ${statusCls(r[3])}">${esc(r[3])}</span></td><td><button data-detail="${esc(r[0])}" class="quiet-link">View ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table>${!rows.length?`<div class="empty">${icon('search')}<strong>No matching records</strong>Try clearing your search or changing the status filter.</div>`:''}</div></div>${catalogGuide(page)}<div class="banner-note">${icon('shield')} This is a preview of the ${esc(page)} interface. Changes stay in your browser; no company systems are affected.</div>`}
function editionSelector(){return `<div class="list-guide">${Object.entries(editionMeta).map(([k,v])=>`<button class="guide-card" data-edition="${k}" style="padding:25px;text-align:left"><strong style="font-size:20px;color:var(--blue)">${k}</strong><strong>${esc(v.full)}</strong>${esc(v.desc)}<br><br>Explore edition →</button>`).join('')}</div>`}
const posProducts=[['Wireless mouse',8500],['Cotton shirt',12500],['Bluetooth speaker',28000],['Power bank',19500],['Notebook set',4200],['Water bottle',7600]];
function posPage(){return `<div class="twocol"><div class="card panel"><div class="panel-top"><h2>Retail product catalogue</h2><span>Demo POS</span></div><div class="list-guide">${posProducts.map((p,i)=>`<button data-pos-add="${i}" class="guide-card" style="cursor:pointer;text-align:left"><strong>${esc(p[0])}</strong>₦${p[1].toLocaleString()}<br><br><span style="color:var(--blue)">+ Add to cart</span></button>`).join('')}</div></div><div class="card panel"><div class="panel-top"><h2>Current sale</h2><span>${S.cart.length} items</span></div>${S.cart.length?S.cart.map((it,i)=>`<div class="list-item"><span style="flex:1"><strong>${esc(it[0])}</strong><small>₦${it[1].toLocaleString()}</small></span><button data-pos-remove="${i}" class="secondary">Remove</button></div>`).join(''):'<div class="empty">Add products to begin a demonstration sale</div>'}<div style="font-size:20px;font-weight:800;margin:23px 0">Total: ₦${S.cart.reduce((a,b)=>a+b[1],0).toLocaleString()}</div><button class="primary" style="width:100%" data-action="pos-checkout" ${S.cart.length?'':'disabled'}>Complete demo sale</button><div class="banner-note">No real payment is processed.</div></div></div>`}
function feedbackPage(){return `<div class="twocol"><div class="card panel"><h2>Share your experience</h2><p style="color:var(--muted);font-size:12px">We welcome navigation, usability and workflow feedback.</p><button class="primary" style="margin-top:16px" data-action="feedback">Leave feedback</button></div><div class="card panel"><h2>Feedback you've saved in this browser</h2>${S.feedback.length?S.feedback.map(f=>`<div class="feedback-item"><strong>${esc(f.edition)} · ${esc(f.page)}</strong><p>${esc(f.message)}</p><small>${esc(f.created)}</small></div>`).join(''):'<div class="empty">No feedback saved yet</div>'}<button class="secondary" data-action="export-feedback">${icon('download')} Download feedback</button></div></div>`}
function detailPage(){const row=rowsFor(S.page).find(r=>r[0]===S.detail)||[S.detail,'Inventory record','Operations','Pending'];return `<div class="card panel"><button data-action="detail-back" class="quiet-link">← Back to ${esc(S.page)}</button><h2 style="font-size:22px;margin-bottom:6px">${esc(row[1])}</h2><div style="color:var(--muted);font-size:12px">${esc(row[0])} · ${esc(row[2])}</div><div style="margin:18px 0"><span class="status ${statusCls(row[3])}">${esc(row[3])}</span></div><div class="list-guide"><div class="guide-card"><strong>Reference</strong>${esc(row[0])}</div><div class="guide-card"><strong>Responsible</strong>${esc(row[2])}</div><div class="guide-card"><strong>Current status</strong>${esc(row[3])}</div></div><div style="margin-top:25px"><h3>Record activity</h3>${['Record created','Reviewed by Operations','Current status recorded'].map((x,i)=>`<div class="list-item">${icon('clock')}<span>${esc(x)}</span><small style="margin-left:auto;color:var(--muted)">${i+1}d ago</small></div>`).join('')}</div><div class="actions" style="margin-top:21px"><button class="primary" data-action="note-record">Add note</button><button class="secondary" data-action="feedback">Comment on design</button></div></div>`}
function modal(){if(!S.modal)return '';if(S.modal==='tour'){const steps=[['Find your way around','Switch between PIM, RIM and TIM from the product selector in the sidebar.'],['Manage your day','Use My to-do and activity updates to follow items that need action.'],['Create records','Choose Create New or a Quick Action to start a request, order or issue.'],['Review and refine','Search records, inspect details, and use Give feedback to share suggestions.']];const step=steps[S.tourStep||0];return `<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal classic-tour-dialog" role="dialog" aria-modal="true" aria-label="PRIME quick tour"><div class="modal-head"><div><h2>Welcome to PRIME</h2><p>Quick tour · Step ${(S.tourStep||0)+1} of ${steps.length}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close tour">${icon('close')}</button></div><div class="classic-tour-body"><span class="classic-tour-step">${(S.tourStep||0)+1}</span><h3>${step[0]}</h3><p>${step[1]}</p></div><div class="modal-foot"><button class="secondary" data-action="tour-back" ${(S.tourStep||0)===0?'disabled':''}>Back</button><button class="primary" data-action="tour-next">${(S.tourStep||0)===steps.length-1?'Finish':'Next'} ${icon('arrow')}</button></div></div></div>`;}if(S.modal==='quick'){return `<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="Start something"><div class="modal-head"><div><h2>Start something</h2><p>Choose an action for ${S.edition}</p></div><button class="icon-btn" data-action="close-modal">${icon('close')}</button></div><div class="modal-grid">${editionMeta[S.edition].actions.map(a=>`<button class="modal-choice" data-form="${esc(a)}">${icon('plus')}${esc(a)}</button>`).join('')}</div></div></div>`}
if(S.modal==='feedback'){return `<div class="modal-backdrop" data-action="modal-backdrop"><form class="modal" id="feedback-form" role="dialog" aria-modal="true" aria-label="Give feedback"><div class="modal-head"><div><h2>Feedback on PRIME</h2><p>Tell us what needs changing on ${S.edition} / ${esc(S.page)}</p></div><button type="button" class="icon-btn" data-action="close-modal">${icon('close')}</button></div><div class="field"><label for="fb-rating">Type of feedback</label><select id="fb-rating" name="rating"><option>Usability issue</option><option>Missing feature</option><option>Visual improvement</option><option>Positive feedback</option><option>Other</option></select></div><div class="field"><label for="fb-text">What would you change?</label><textarea id="fb-text" name="message" minlength="4" required placeholder="Describe the screen, issue and what you expected..."></textarea></div><div class="field"><label for="fb-name">Your name (optional)</label><input id="fb-name" name="name" placeholder="Optional"></div><div class="info-bar" style="margin-top:17px">${icon('alert')} This demo stores feedback in your browser only. Export it to share with the PRIME team.</div><div class="modal-foot"><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary" type="submit">Save feedback</button></div></form></div>`}
return `<div class="modal-backdrop" data-action="modal-backdrop"><form class="modal" id="record-form" role="dialog" aria-modal="true" aria-label="Create ${esc(S.modal)}"><div class="modal-head"><div><h2>${esc(S.modal)}</h2><p>Create a sample draft in ${S.edition}. This does not update production data.</p></div><button type="button" class="icon-btn" data-action="close-modal">${icon('close')}</button></div><div class="field"><label for="record-title">Record name or description</label><input name="title" id="record-title" placeholder="Enter item, tool or request" required minlength="3"></div><div class="field"><label for="record-owner">Assigned person or location</label><input name="owner" id="record-owner" placeholder="e.g. Engineering"></div><div class="field"><label for="record-note">Details (optional)</label><textarea id="record-note" name="note" placeholder="Add context for this draft"></textarea></div><div class="modal-foot"><button type="button" class="secondary" data-action="close-modal">Cancel</button><button type="submit" class="primary">Save draft</button></div></form></div>`}
function layout(){return `<div class="app ${S.compact?'compact-layout':''}">${sidebar()}<div class="workspace">${topbar()}<main class="main">${topIntro()}${S.detail?detailPage():['PRIME Overview','My Products'].includes(S.page)?primeOverview():S.page==='Home'?overview():modulePage()}</main></div>${mobileNav()}${S.mobile?`<div class="drawer-backdrop" data-action="mobile-close"></div><aside class="drawer">${sidebar().replace('class="sidebar"','class="sidebar" style="position:relative;width:100%;height:100%;display:flex;border:0"')}</aside>`:''}${modal()}${S.toast?`<div class="toast" role="status">${esc(S.toast)}</div>`:''}</div>`}
const dashboardExpandedSections=new Set();
function setupDashboardAccordions(){
 const titles=['My to-do','Stock health','Recent activity','My material requests','Get started','Quick tour'];
 const panels=[...document.querySelectorAll('.classic-lower .classic-panel, .classic-lower .classic-tour')];
 panels.forEach((panel,index)=>{
  const id='dashboard-section-'+index;
  const header=panel.querySelector('.classic-panel-head')||panel.querySelector('.classic-tour-copy');
  if(!header)return;
  const open=dashboardExpandedSections.has(id);
  panel.classList.add('dashboard-accordion');
  panel.classList.toggle('dashboard-accordion-closed',!open);
  const title=panel.querySelector('h2,h3')?.textContent?.trim()||titles[index]||'Section';
  const button=document.createElement('button');
  button.type='button';button.className='dashboard-accordion-toggle';
  button.setAttribute('aria-expanded',String(open));
  button.setAttribute('aria-label',(open?'Collapse ':'Expand ')+title);
  button.textContent=(open?'−':'+');
  header.appendChild(button);
  button.addEventListener('click',()=>{
   if(dashboardExpandedSections.has(id))dashboardExpandedSections.delete(id);
   else dashboardExpandedSections.add(id);
   const nowOpen=dashboardExpandedSections.has(id);
   panel.classList.toggle('dashboard-accordion-closed',!nowOpen);
   button.textContent=nowOpen?'−':'+';
   button.setAttribute('aria-expanded',String(nowOpen));
   button.setAttribute('aria-label',(nowOpen?'Collapse ':'Expand ')+title);
  });
 });
}
function draw(){document.title=`${S.page} · ${S.edition} · PRIME`;ROOT.innerHTML=layout();setupDashboardAccordions();if(S.toast){clearTimeout(draw.toastTimer);draw.toastTimer=setTimeout(()=>{S.toast='';const toast=document.querySelector('.toast');if(toast)toast.remove()},3800)}}
function toast(m){S.toast=m;draw()}
function csvDownload(name,rows){const data=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');download(name,new Blob([data],{type:'text/csv;charset=utf-8'}))}
function download(name,blob){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function action(act,el){if(act==='quick-tour'){S.tourStep=0;S.modal='tour';draw()}else if(act==='tour-next'){if((S.tourStep||0)>=3){S.modal=null;S.tourStep=0}else S.tourStep++;draw()}else if(act==='tour-back'){S.tourStep=Math.max(0,(S.tourStep||0)-1);draw()}else if(act==='edition-toggle'){S.parentMenu=!S.parentMenu;draw()}else if(act==='expand'){const key=S.edition+':'+el.dataset.name;S.groupExpanded[key]=!S.groupExpanded[key];draw()}else if(act==='mobile'){S.mobile=!S.mobile;draw()}else if(act==='mobile-close'){S.mobile=false;draw()}else if(act==='quick'){S.modal='quick';draw()}else if(act==='quick-toggle'){S.quickOpen=!S.quickOpen;draw()}else if(act==='company-toggle'){S.companyOpen=!S.companyOpen;draw()}else if(act==='sidebar-collapse'){S.compact=!S.compact;draw()}else if(act==='section-toggle'){S.sideSections[el.dataset.name]=S.sideSections[el.dataset.name]===false;draw()}else if(act==='prime-overview'){navigate('PRIME Overview')}else if(act==='subscription'){navigate('Billing')}else if(act==='profile'){S.profileMenu=false;navigate('Profile')}else if(act==='explore'){toast(el.dataset.name+' is available to explore in a future PRIME product release.')}else if(act==='close-modal'||act==='modal-backdrop'){S.modal=null;draw()}else if(act==='feedback'){S.modal='feedback';draw()}else if(act==='support'){navigate('Help');toast('Contact support is a prototype. Use Give feedback to record a request locally.')}else if(act==='profile-menu-toggle'){S.profileMenu=!S.profileMenu;draw()}else if(act==='sign-out'){S.profileMenu=false;toast('Sign out is disabled for this public demo.')}else if(act==='period-toggle'){S.periodOpen=!S.periodOpen;draw()}else if(act==='period-set'){S.period=el.dataset.period||'This week';S.periodOpen=false;draw()}else if(act==='focus-search'){document.getElementById('global-search')?.focus()}else if(act==='navigate'){navigate(el.dataset.name)}else if(act==='detail-back'){S.detail=null;draw()}else if(act==='note-record'){S.modal='Add record note';draw()}else if(act==='export'){csvDownload('prime-'+S.edition.toLowerCase()+'-'+idOf(S.page)+'.csv',[['Reference','Item','Person or location','Status'],...rowsFor(S.page)])}else if(act==='export-feedback'){download('prime-feedback.json',new Blob([JSON.stringify(S.feedback,null,2)],{type:'application/json'}));toast('Your browser feedback was exported.')}else if(act==='pos-checkout'){if(!S.cart.length)return;S.cart=[];toast('Demo sale completed. No payment taken.')}else if(act==='open-editions'){navigate('Edition selector')} }
ROOT.addEventListener('click',e=>{const ed=e.target.closest('[data-edition]');if(ed){switchEdition(ed.dataset.edition);return}const form=e.target.closest('[data-form]');if(form){S.modal=form.dataset.form;draw();return}const nav=e.target.closest('[data-nav]');if(nav){const expandTarget=e.target.closest('[data-action="expand"]');if(expandTarget){action('expand',expandTarget);return}const name=nav.dataset.nav;const group=S.edition+':'+name;const groupEntry=allNav().flatMap(g=>g[1]).find(([n,ch])=>n===name&&ch.length);if(groupEntry)S.groupExpanded[group]=!S.groupExpanded[group];navigate(name);return}const detail=e.target.closest('[data-detail]');if(detail){S.detail=detail.dataset.detail;draw();return}const add=e.target.closest('[data-pos-add]');if(add){S.cart.push([...posProducts[Number(add.dataset.posAdd)]]);draw();return}const remove=e.target.closest('[data-pos-remove]');if(remove){S.cart.splice(Number(remove.dataset.posRemove),1);draw();return}const a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='modal-backdrop'&&e.target!==a)return;action(a.dataset.action,a)}});
ROOT.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form);if(form.id==='record-form'){const title=String(fd.get('title')||'').trim();if(title.length<3)return;const rec={ref:S.edition+'-DEMO-'+String(S.records.length+1).padStart(4,'0'),title,owner:String(fd.get('owner')||'Demo workspace'),note:String(fd.get('note')||''),module:getGroup(S.page),edition:S.edition,status:'Draft'};S.records.unshift(rec);persist('prime:records',S.records);S.modal=null;S.detail=null;toast('Demo draft saved in this browser.')} else if(form.id==='feedback-form'){const message=String(fd.get('message')||'').trim();if(message.length<4)return;S.feedback.unshift({edition:S.edition,page:S.page,kind:String(fd.get('rating')||''),name:String(fd.get('name')||''),message,created:new Date().toISOString()});persist('prime:feedback',S.feedback);S.modal=null;toast('Feedback saved locally. Export it from Help → Leave feedback to share.')}});
ROOT.addEventListener('input',e=>{if(e.target.id==='global-search'){const selectionStart=e.target.selectionStart;S.search=e.target.value;const list=document.querySelector('.table-scroller');if(list&&!S.detail){const container=document.createElement('div');container.innerHTML=modulePage();let replacement=container.querySelector('.table-scroller');if(replacement)list.replaceWith(replacement)}}});
ROOT.addEventListener('change',e=>{if(e.target.id==='status-filter'){S.status=e.target.value;draw()}});
window.addEventListener('hashchange',()=>{let old=JSON.stringify([S.edition,S.page]);initialRoute();if(old!==JSON.stringify([S.edition,S.page]))draw()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&(S.modal||S.mobile)){S.modal=null;S.mobile=false;draw()}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();document.getElementById('global-search')?.focus()}});
initialRoute();draw();
